mapper.select:
SELECT c.user_id, p.post_name, c.id, p.related_user_names, p.org_name, p.operate_time, d.name as level_name, p.org_id, p.icon_url, c.checked FROM tb_functional_department_coop c LEFT JOIN tb_collaboration_post p ON c.user_id = p.id LEFT JOIN tb_functional_department d ON c.dept_id = d.id WHERE c.is_deleted = 0 and p.deleted = 0 and d.is_deleted = 0
and p.post_name like concat('%', #{name}, '%')
and c.dept_id = #{deptId}
AND p.operate_time >= #{startTime}
AND p.operate_time <=CONCAT(#{endTime}, ' 23:59:59')

